    @EventHandler( payloadType=UpdateBranchEvent.class )
    public void handle( UpdateBranchEvent event) {
    	LOGGER.info("handling UpdateBranchEvent - " + event );
    	
	    Branch entity = new Branch();
            entity.setBranchId( event.getBranchId() );
            entity.setName( event.getName() );
            entity.setBranchCode( event.getBranchCode() );
            entity.setAddress( event.getAddress() );
            entity.setPhone( event.getPhone() );
            entity.setOpeningHours( event.getOpeningHours() );
            entity.setBank( event.getBank() );
            entity.setAccounts( event.getAccounts() );
            entity.setLoanAccounts( event.getLoanAccounts() );
            entity.setAtms( event.getAtms() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindBranch( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllBranch( entity );        
    }
    
