    /**
     * Method to retrieve the Branch via an BranchPrimaryKey.
     * @param 	id Long
     * @return 	Branch
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Branch handle( FindBranchQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getBranchId() );
    }
    
    /**
     * Method to retrieve a collection of all Branchs
     *
     * @param	query	FindAllBranchQuery 
     * @return 	List<Branch> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Branch> handle( FindAllBranchQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindBranch,
 * but only if the id matches
 *
 * @param		entity	Branch
 */
	protected void emitFindBranch( Branch entity ) {
		LOGGER.info("handling emitFindBranch" );
		
	    queryUpdateEmitter.emit(FindBranchQuery.class,
	                            query -> query.getFilter().getBranchId().equals(entity.getBranchId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBranch
	 * 
	 * @param		entity	Branch
	 */
	protected void emitFindAllBranch( Branch entity ) {
		LOGGER.info("handling emitFindAllBranch" );
		
	    queryUpdateEmitter.emit(FindAllBranchQuery.class,
	                            query -> true,
	                            entity);
	}

